"""Verify and summarize only outputs generated by a local reproduction run."""

from __future__ import annotations

import argparse
import json
import math
import os
import sys
import tempfile
from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any

from .provenance import SourceCompatibilityError, verify_source_tree
from .spec import RunSpec, load_study, main_runs, smoke_runs

SOURCE_REVISION = str(load_study()["source_revision"])
REPRODUCTION_DIR = Path(__file__).resolve().parent.parent
REPOSITORY_ROOT = Path(
    os.environ.get("WSI_LAB_SOURCE_ROOT", REPRODUCTION_DIR.parents[1] / "wsi-lab")
).expanduser().resolve()


class SummaryError(RuntimeError):
    """A generated run is missing or violates the study contract."""


def _activate_source(path: str | Path) -> Path:
    source_root = Path(path).expanduser().resolve()
    source = load_study()["source_tree"]
    try:
        verify_source_tree(
            source_root,
            expected_sha256=str(source["sha256"]),
            expected_files=int(source["python_files"]),
        )
    except (KeyError, TypeError, SourceCompatibilityError) as exc:
        raise SummaryError(
            "the selected source root does not match the recorded implementation"
        ) from exc
    source_path = str(source_root / "src")
    if source_path not in sys.path:
        sys.path.insert(0, source_path)
    os.environ["WSI_LAB_SOURCE_ROOT"] = str(source_root)
    return source_root


def _read_object(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise SummaryError(f"could not read {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise SummaryError(f"expected a JSON object: {path}")
    return value


def _expected_step(row: RunSpec) -> int:
    if row.mode == "smoke":
        return 1_024
    batch = 8 * 128
    return math.ceil(2_000_000 / batch) * batch


def _manifest_by_run(work_root: Path) -> dict[str, tuple[Path, dict[str, Any]]]:
    result: dict[str, tuple[Path, dict[str, Any]]] = {}
    root = work_root / "shared_workspace" / "rl_ablation"
    for path in sorted(root.glob("*/run_manifest.json")):
        value = _read_object(path)
        run_id = str(value.get("run_id", ""))
        if not run_id:
            raise SummaryError(f"run manifest has no run_id: {path}")
        if run_id in result:
            raise SummaryError(f"duplicate generated run_id: {run_id}")
        result[run_id] = (path, value)
    return result


def summarize(work_root: str | Path, *, mode: str) -> dict[str, Any]:
    """Verify the complete selected matrix and aggregate its episode telemetry."""

    from .verification import VerificationError, verify_completed_run

    root = Path(work_root).expanduser().resolve()
    expected = main_runs() if mode == "main" else smoke_runs()
    discovered = _manifest_by_run(root)
    summaries: list[dict[str, Any]] = []
    for row in expected:
        entry = discovered.get(row.run_id)
        if entry is None:
            raise SummaryError(f"missing generated run: {row.run_id}")
        path, manifest = entry
        expected_run = {
            "source_revision": SOURCE_REVISION,
            "run_id": row.run_id,
            "mode": row.mode,
            "variant": row.variant,
            "start": row.start,
            "seed": row.seed,
            "expected_final_step": _expected_step(row),
        }
        try:
            verified = verify_completed_run(expected_run, manifest_path=path)
        except (KeyError, TypeError, ValueError, VerificationError) as exc:
            raise SummaryError(f"generated run failed verification: {row.run_id}: {exc}") from exc
        summaries.append(
            {
                "run_id": row.run_id,
                "variant": row.variant,
                "start": row.start,
                "seed": row.seed,
                "global_step": int(manifest["global_step"]),
                "telemetry": verified["telemetry"],
            }
        )
    return {
        "schema_version": 1,
        "study_id": "camelyon16-rl-ablation-2m",
        "mode": mode,
        "source_revision": SOURCE_REVISION,
        "training_only": True,
        "run_count": len(summaries),
        "runs": summaries,
    }


def _atomic_json(path: Path, value: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary: Path | None = None
    try:
        with tempfile.NamedTemporaryFile(
            mode="w",
            encoding="utf-8",
            dir=path.parent,
            prefix=f".{path.name}.",
            suffix=".tmp",
            delete=False,
        ) as stream:
            temporary = Path(stream.name)
            json.dump(value, stream, indent=2, sort_keys=True, allow_nan=False)
            stream.write("\n")
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
    except BaseException:
        if temporary is not None:
            temporary.unlink(missing_ok=True)
        raise


def _safe_output_path(path: str | Path) -> Path:
    output = Path(path).expanduser().resolve()
    if output == REPRODUCTION_DIR or output.is_relative_to(REPRODUCTION_DIR):
        raise SummaryError("summary output must be outside the committed reproduction package")
    ignored_workspace = REPOSITORY_ROOT / "workspace"
    if output.is_relative_to(REPOSITORY_ROOT) and not output.is_relative_to(ignored_workspace):
        raise SummaryError(
            "summary output inside this repository must be beneath its ignored workspace/ directory"
        )
    return output


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--work-root", required=True, type=Path)
    parser.add_argument(
        "--source-root",
        type=Path,
        default=REPOSITORY_ROOT,
        help="checkout providing the recorded src/wsi_lab implementation",
    )
    parser.add_argument("--mode", choices=("main", "smoke"), default="main")
    parser.add_argument(
        "--output",
        type=Path,
        help="destination JSON; defaults beneath WORK_ROOT/summaries",
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    arguments = _parser().parse_args(argv)
    work_root = arguments.work_root.expanduser().resolve()
    output_candidate = (
        arguments.output
        if arguments.output is not None
        else work_root / "summaries" / f"{arguments.mode}_summary.json"
    )
    try:
        _activate_source(arguments.source_root)
        output = _safe_output_path(output_candidate)
        report = summarize(work_root, mode=arguments.mode)
        _atomic_json(output, report)
    except SummaryError as exc:
        print(f"error: {exc}")
        return 2
    print(f"verified {report['run_count']} {arguments.mode} runs")
    print(f"summary={output}")
    return 0


__all__ = ["SummaryError", "main", "summarize"]


if __name__ == "__main__":
    raise SystemExit(main())
